mapper.insert:
INSERT INTO consult_record (
    appointment_id, doctor_id, patient_id, status, chief_complaint,
    history_of_present_illness, attachments, pre_consultation_submitted_at,
    created_at, updated_at
) VALUES (
    #{record.appointmentId}, #{record.doctorId}, #{record.patientId}, #{record.status},
    #{record.chiefComplaint}, #{record.historyOfPresentIllness},
    CAST(#{record.attachmentsJson, jdbcType=VARCHAR} AS jsonb),
    #{record.preConsultationSubmittedAt}, #{record.createdAt}, #{record.updatedAt}
)

mapper.update:
UPDATE consult_record
SET status = #{record.status},
    chief_complaint = #{record.chiefComplaint},
    history_of_present_illness = #{record.historyOfPresentIllness},
    attachments = CAST(#{record.attachmentsJson, jdbcType=VARCHAR} AS jsonb),
    pre_consultation_submitted_at = #{record.preConsultationSubmittedAt},
    updated_at = #{record.updatedAt}
WHERE id = #{record.id}
  AND status = #{expectedStatus}
  AND deleted_at IS NULL

mapper.select:
SELECT cr.id, cr.appointment_id, d.name AS doctor_name, cr.status, cr.updated_at
FROM consult_record cr
LEFT JOIN doctor d ON d.id = cr.doctor_id
WHERE cr.patient_id = #{patientId}
  AND cr.deleted_at IS NULL

    AND cr.status = #{status}

ORDER BY cr.updated_at DESC, cr.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM consult_record
WHERE patient_id = #{patientId}
  AND deleted_at IS NULL

    AND status = #{status}
